    const callback = this.markChildrenAsProdDeps.bind(this);
    for (const key of Object.keys(childPackageJson.dependencies || {}).concat(
      Object.keys(childPackageJson.optionalDependencies || {}),
    )) {
      if (this.prodDeps.has(key)) {
