function getPlatformUrlPrefix(hostOS: string, hostArch: string) {
  const prefixMap: Record<string, string> = {
    linux: 'Linux_x64',
    darwin: 'Mac',
    win32: 'Win',
  };
  let prefix = prefixMap[hostOS];
  if (prefix === 'Mac' && hostArch === 'arm64') {
